UPDATE content_cards SET content_json=json_set(content_json,'$.facts',json('["Sunday · 2:10 PM"]')) WHERE id='sunday-gatherings' AND status='draft' AND COALESCE(json_extract(content_json,'$.hold'),0)=0 AND json_extract(content_json,'$.isSynthetic')=0 AND json_extract(content_json,'$.sourceStatus')='draft' AND json_extract(content_json,'$.schemaVersion')=2 AND json_extract(content_json,'$.summary')='We gather to hear God’s Word, worship together and encourage one another.' AND json(json_extract(content_json,'$.facts'))=json('[]');
UPDATE content_cards SET content_json=json_set(content_json,'$.sections[1].paragraphs',json('["God is holy, all-powerful, all-knowing, present everywhere and unchanging. Our life and existence depend on him. He is entirely trustworthy, loving, compassionate and faithful to his people and promises.","References: Exodus 3:14; Numbers 23:19; Leviticus 11:44-45, 19:2; Psalm 11:4-6; Malachi 3:6; John 3:16, 4:24, 5:26; Acts 17:28; Romans 3:3-4"]'),'$.sections[2].paragraphs',json('["Jesus Christ is fully human and fully God. He alone restores our relationship with God. Born of a virgin, he lived a perfect life and took our place, meeting God’s demand for perfection. Through his resurrection he defeated death so that we could have life.","References: Isaiah 7:14, 53:7; Matthew 1:18-25, 3:17, 8:29, 14:33, 16:16, 28:5-6; Luke 1:35, 22:70, 24:46-47; John 1:1, 1:14, 10:30, 11:25-27, 17:1-5; Acts 1:9, 2:22-24, 7:55-56; Romans 1:3-4, 3:23-26, 8:1-3, 10:4, I Corinthians 8:6,; II Corinthians 5:19-21; Galatians 4:4-5; Philippians 2:5-11; Colossians 1:15, 2:9; I Timothy 2:5-6, 3:16"]'),'$.sections[3].paragraphs',json('["The Holy Spirit assures believers that they belong to Christ, guides them into truth and brings glory to Jesus. He convicts people of sin, God’s righteousness and the judgment to come. He comforts us, gives spiritual gifts and shapes us to become more like Christ.","References: Genesis 1:2; Psalms 51:11, 139:7; Isaiah 61:1-3; Joel 2:28-32; Mark 1:10; Luke 1:35, 4:1, 11:13, 12:12; John 15:26, 16:7-14; Acts 1:8, 2:1-4, 13:2; Romans 8:9-11; I Corinthians 3:16, Ephesians 1:13-14, II Peter 1:21; Revelation 22:17"]'),'$.sections[4].paragraphs',json('["We were created to glorify God forever. Through Jesus’ death and resurrection, forgiveness, salvation and resurrection into eternal union with God are possible. Eternal separation from God because of sin is hell; eternal union with him is heaven.","References: Isaiah 43:7; John 3:16, 3:36; Romans 6:23; I Corinthians 15:12-58; I John 2:25, 5:11-13; Revelation 20:15"]'),'$.sections[5].paragraphs',json('["God made people in his image, giving humanity the highest place in his creation. We were made for fellowship with God, but sinful disobedience separated us from him. We cannot repair that relationship through our own effort. Each person has God-given dignity and deserves respect and Christian love.","References: Genesis 1:26-30, 2:7, 2:18-22; Psalms 8:3-6, 32:1-5, 51:5; Isaiah 6:5; Jeremiah 17:5; Acts 17:26-31; Romans 1:19-32, 3:10-18, 3:23, 5:6, 6:6, 7:14-25; I Corinthians 1:21-31, 15:19; Ephesians 2:1-22; Colossians 1:21-22, 3:9-11"]'),'$.sections[7].paragraphs',json('["After coming to faith in Jesus Christ, believers are commanded in Scripture to be baptized in water in the name of the Father, Son and Holy Spirit.","In the Lord’s Supper, we share communion in God’s presence. Bread and wine or grape juice represent Jesus’ body and blood as we remember his sacrifice on the cross."]')) WHERE id='what-we-believe' AND status='draft' AND COALESCE(json_extract(content_json,'$.hold'),0)=0 AND json_extract(content_json,'$.isSynthetic')=0 AND json_extract(content_json,'$.sourceStatus')='draft' AND json_extract(content_json,'$.schemaVersion')=2 AND json_array_length(json_extract(content_json,'$.sections'))=8 AND json_extract(content_json,'$.sections[0].heading')='Trinity' AND json(json_extract(content_json,'$.sections[0].paragraphs'))=json('["One God exists eternally as Father, Son and Holy Spirit, coequal and coeternal."]') AND json_extract(content_json,'$.sections[1].heading')='The Father' AND json(json_extract(content_json,'$.sections[1].paragraphs'))=json('["God is holy, powerful, all-knowing, ever-present and unchanging; he is loving, compassionate and faithful.","References: Exodus 3:14; Numbers 23:19; Leviticus 11:44-45, 19:2; Psalm 11:4-6; Malachi 3:6; John 3:16, 4:24, 5:26; Acts 17:28; Romans 3:3-4"]') AND json_extract(content_json,'$.sections[2].heading')='The Son' AND json(json_extract(content_json,'$.sections[2].paragraphs'))=json('["Jesus is fully human and fully God. Born of a virgin, he lived without sin, died for us and rose again.","References: Isaiah 7:14, 53:7; Matthew 1:18-25, 3:17, 8:29, 14:33, 16:16, 28:5-6; Luke 1:35, 22:70, 24:46-47; John 1:1, 1:14, 10:30, 11:25-27, 17:1-5; Acts 1:9, 2:22-24, 7:55-56; Romans 1:3-4, 3:23-26, 8:1-3, 10:4, I Corinthians 8:6,; II Corinthians 5:19-21; Galatians 4:4-5; Philippians 2:5-11; Colossians 1:15, 2:9; I Timothy 2:5-6, 3:16"]') AND json_extract(content_json,'$.sections[3].heading')='The Holy Spirit' AND json(json_extract(content_json,'$.sections[3].paragraphs'))=json('["The Holy Spirit guides and comforts believers, convicts of sin, gives spiritual gifts and makes us more like Christ.","References: Genesis 1:2; Psalms 51:11, 139:7; Isaiah 61:1-3; Joel 2:28-32; Mark 1:10; Luke 1:35, 4:1, 11:13, 12:12; John 15:26, 16:7-14; Acts 1:8, 2:1-4, 13:2; Romans 8:9-11; I Corinthians 3:16, Ephesians 1:13-14, II Peter 1:21; Revelation 22:17"]') AND json_extract(content_json,'$.sections[4].heading')='Eternity' AND json(json_extract(content_json,'$.sections[4].paragraphs'))=json('["Through Jesus’ death and resurrection, forgiveness and eternal life are possible. Separation from God is hell; union with him is heaven.","References: Isaiah 43:7; John 3:16, 3:36; Romans 6:23; I Corinthians 15:12-58; I John 2:25, 5:11-13; Revelation 20:15"]') AND json_extract(content_json,'$.sections[5].heading')='Humanity' AND json(json_extract(content_json,'$.sections[5].paragraphs'))=json('["People bear God’s image and possess dignity. Sin separates us from God; we cannot restore that relationship through our own effort.","References: Genesis 1:26-30, 2:7, 2:18-22; Psalms 8:3-6, 32:1-5, 51:5; Isaiah 6:5; Jeremiah 17:5; Acts 17:26-31; Romans 1:19-32, 3:10-18, 3:23, 5:6, 6:6, 7:14-25; I Corinthians 1:21-31, 15:19; Ephesians 2:1-22; Colossians 1:21-22, 3:9-11"]') AND json_extract(content_json,'$.sections[6].heading')='Second Coming' AND json(json_extract(content_json,'$.sections[6].paragraphs'))=json('["Jesus will return physically and visibly to make all things new. Scripture does not disclose the date.","References: Acts 1:9-11; I Thessalonians 4:15-17; II Thessalonians 1:7-8; Colossians 3:4; Revelation 21:5"]') AND json_extract(content_json,'$.sections[7].heading')='Two Sacraments' AND json(json_extract(content_json,'$.sections[7].paragraphs'))=json('["Baptism follows faith in Jesus and is in the name of the Father, Son and Holy Spirit.","In the Lord’s Supper, bread and wine or grape juice represent Jesus’ body and blood, remembering his sacrifice."]');
